import bundledProgress from "../../public/data/progress.json";
import bundledSubmitters from "../../public/data/submitters.json";

// Data of the /progress visual. The source of truth is SAAF-Project/website/data/, regenerated by a GitHub Action
// whenever plans/ changes on main (tools/scripts/generate_dashboard.py). The repo is private, so it is read through the
// GitHub API with the server-side token, like /api/plan-content. If that fails (no token, rate limit, outage) the
// copy bundled with the portal is used instead, and the caller is told which one it got.

const REPO = "SAAF-Project/SAAF-Project";
const REVALIDATE_SECONDS = 600; // same as the repo list: the data changes when plans change, not by the minute

export type DataSource = "live" | "bundled";

export interface Loaded<T> {
  data: T;
  source: DataSource;
}

type Check<T> = (value: unknown) => value is T;

async function fetchLive<T>(file: string, check: Check<T>, fetchImpl: typeof fetch): Promise<T | null> {
  const token = process.env.GITHUB_PAT;
  if (!token) return null;
  try {
    const res = await fetchImpl(`https://api.github.com/repos/${REPO}/contents/website/data/${file}`, {
      headers: { Authorization: `Bearer ${token}`, Accept: "application/vnd.github.raw+json" },
      next: { revalidate: REVALIDATE_SECONDS },
    });
    if (!res.ok) return null;
    const json: unknown = await res.json();
    return check(json) ? json : null;
  } catch {
    return null;
  }
}

interface ProgressShape {
  schema_version: number;
  parts: unknown[];
  plans: unknown[];
  annex: unknown;
}

/** progress.json must be the schema this module was built for, or it is not used. */
export const isProgress: Check<ProgressShape> = (v): v is ProgressShape => {
  const p = v as Partial<ProgressShape> | null;
  return !!p && p.schema_version === 2 && Array.isArray(p.parts) && Array.isArray(p.plans) && !!p.annex;
};

export const isSubmitters: Check<{ name: string; plans: string[] }[]> = (v): v is { name: string; plans: string[] }[] =>
  Array.isArray(v) && v.every((s) => typeof s?.name === "string" && Array.isArray(s?.plans));

export async function loadProgress(fetchImpl: typeof fetch = fetch): Promise<Loaded<unknown>> {
  const live = await fetchLive("progress.json", isProgress, fetchImpl);
  return live ? { data: live, source: "live" } : { data: bundledProgress, source: "bundled" };
}

export async function loadSubmitters(fetchImpl: typeof fetch = fetch): Promise<Loaded<unknown>> {
  const live = await fetchLive("submitters.json", isSubmitters, fetchImpl);
  return live ? { data: live, source: "live" } : { data: bundledSubmitters, source: "bundled" };
}
